/* ================================================================== * 월 정산 리포트 (레거시) - 채널/등급/카테고리/월별 매출 · 결제 · 반품 · 배송 * 2009 최초 작성, 2014 채널 추가, 2018 쿠폰/반품 반영, 2021 B2B 추가 * 주의: 결제는 LEGACY 스키마 테이블 사용, 취소(99) 주문은 제외 * ================================================================== */ WITH ORD_BASE AS ( /* 기준 주문: 기간/상태/채널 조건은 화면에서 동적으로 들어온다 */ SELECT O.ORD_NO, O.CUST_NO, O.ORD_DT, O.ORD_STAT_CD, O.TOT_AMT, O.ORD_CHNL_CD, O.SALE_EMP_NO, TO_CHAR(O.ORD_DT, 'YYYYMM') AS ORD_YM, C.CUST_NM AS CUST_NAME, C.RGN_CD AS CUST_RGN, NVL(C.CUST_GRD_CD, 'BASIC') AS CUST_GRD FROM TB_ORD_H O INNER JOIN TB_CUST_M C ON C.CUST_NO = O.CUST_NO WHERE O.ORD_STAT_CD <> '99' AND C.USE_YN = 'Y'
O.ORD_CHNL_CD IN #chnlList[]#
C.RGN_CD = #rgnCd#
O.ORD_CHNL_CD <> 'B2B'
), ITEM_AGG AS ( /* 주문별 상품 금액/수량 */ SELECT D.ORD_NO, SUM(D.ORD_QTY * D.UNIT_PRC) AS ITEM_AMT, SUM(D.ORD_QTY) AS ITEM_QTY, COUNT(*) AS ITEM_LINES, COUNT(DISTINCT D.PRD_CD) AS PRD_KINDS FROM TB_ORD_D D WHERE EXISTS (SELECT 1 FROM ORD_BASE B WHERE B.ORD_NO = D.ORD_NO) GROUP BY D.ORD_NO ), PAY_AGG AS ( /* 결제: 레거시 스키마, 결제수단별 분리 */ SELECT P.ORD_NO, SUM(P.PAY_AMT) AS PAY_SUM, SUM(CASE WHEN P.PAY_MTHD_CD = 'CARD' THEN P.PAY_AMT ELSE 0 END) AS CARD_SUM, SUM(CASE WHEN P.PAY_MTHD_CD = 'BANK' THEN P.PAY_AMT ELSE 0 END) AS BANK_SUM, SUM(CASE WHEN P.PAY_MTHD_CD = 'POINT' THEN P.PAY_AMT ELSE 0 END) AS POINT_SUM, MAX(P.PAY_DT) AS LAST_PAY_DT FROM LEGACY.TB_PAY_H P WHERE P.ORD_NO IN (SELECT B.ORD_NO FROM ORD_BASE B) GROUP BY P.ORD_NO ), DLV_LAST AS ( /* 주문별 최종 배송 1건 (ROW_NUMBER) */ SELECT X.ORD_NO, X.DLV_STAT_CD, X.DLV_DT, X.DLV_REQ_DT, X.DLV_CMP_CD FROM ( SELECT V.ORD_NO, V.DLV_STAT_CD, V.DLV_DT, V.DLV_REQ_DT, V.DLV_CMP_CD, ROW_NUMBER() OVER (PARTITION BY V.ORD_NO ORDER BY V.DLV_DT DESC, V.DLV_NO DESC) AS RN FROM TB_DLV_H V WHERE V.DLV_STAT_CD <> 'CANCEL' ) X WHERE X.RN = 1 ), RTN_AGG AS ( SELECT R.ORD_NO, SUM(R.RTN_AMT) AS RTN_SUM, COUNT(*) AS RTN_CNT, MAX(CASE WHEN R.RTN_RSN_CD = 'DEFECT' THEN 1 ELSE 0 END) AS HAS_DEFECT FROM TB_RTN_H R GROUP BY R.ORD_NO ), CPN_AGG AS ( SELECT U.ORD_NO, SUM(U.DC_AMT) AS DC_SUM, COUNT(DISTINCT U.CPN_NO) AS CPN_CNT FROM TB_CPN_U U GROUP BY U.ORD_NO ), EMP_DEPT AS ( /* 영업사원 -> 부서 -> 상위부서 */ SELECT E.EMP_NO, E.EMP_NM, DP.DEPT_NM, UP.DEPT_NM AS UPPER_DEPT_NM FROM TB_EMP_M E LEFT JOIN TB_DEPT_M DP ON DP.DEPT_CD = E.DEPT_CD LEFT JOIN TB_DEPT_M UP ON UP.DEPT_CD = DP.UPPER_DEPT_CD ), CTG_SALES AS ( /* 대분류 카테고리별 매출 */ SELECT D.ORD_NO, NVL(PC.CTG_NM, CT.CTG_NM) AS TOP_CTG_NM, SUM(D.ORD_QTY * D.UNIT_PRC) AS CTG_AMT FROM TB_ORD_D D INNER JOIN TB_PRD_M PR ON PR.PRD_CD = D.PRD_CD INNER JOIN TB_CTG_M CT ON CT.CTG_CD = PR.CTG_CD LEFT JOIN TB_CTG_M PC ON PC.CTG_CD = CT.UPPER_CTG_CD WHERE PR.USE_YN = 'Y' GROUP BY D.ORD_NO, NVL(PC.CTG_NM, CT.CTG_NM) ), R_SEOUL AS ( /* 서울 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'SEOUL' GROUP BY B.CUST_NO ), R_BUSAN AS ( /* 부산 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'BUSAN' GROUP BY B.CUST_NO ), R_DAEGU AS ( /* 대구 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'DAEGU' GROUP BY B.CUST_NO ), R_INCHEON AS ( /* 인천 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'INCHEON' GROUP BY B.CUST_NO ), R_GWANGJU AS ( /* 광주 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'GWANGJU' GROUP BY B.CUST_NO ), R_DAEJEON AS ( /* 대전 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'DAEJEON' GROUP BY B.CUST_NO ), R_ULSAN AS ( /* 울산 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'ULSAN' GROUP BY B.CUST_NO ), R_SEJONG AS ( /* 세종 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'SEJONG' GROUP BY B.CUST_NO ), R_GYEONGGI AS ( /* 경기 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'GYEONGGI' GROUP BY B.CUST_NO ), R_GANGWON AS ( /* 강원 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'GANGWON' GROUP BY B.CUST_NO ), R_CHUNGBUK AS ( /* 충북 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'CHUNGBUK' GROUP BY B.CUST_NO ), R_CHUNGNAM AS ( /* 충남 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'CHUNGNAM' GROUP BY B.CUST_NO ), R_JEONBUK AS ( /* 전북 권역 */ SELECT B.CUST_NO, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VVIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS VIP_AMT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN 