MT, 0) ELSE 0 END) AS GOLD_AMT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS SILVER_AMT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) ELSE 0 END) AS BASIC_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN B.TOT_AMT ELSE 0 END) AS WEB_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN B.TOT_AMT ELSE 0 END) AS APP_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN B.TOT_AMT ELSE 0 END) AS CALL_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN B.TOT_AMT ELSE 0 END) AS STORE_AMT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN B.TOT_AMT ELSE 0 END) AS B2B_AMT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS LATE_CNT, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO WHERE B.CUST_RGN = 'JEJU' GROUP BY B.CUST_NO ), M01 AS ( /* 1월 채널별 실적 */ SELECT B.CUST_NO, /* 웹 */ SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS WEB_NET, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN 1 ELSE 0 END) AS WEB_CNT, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS WEB_RTN, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS WEB_QTY, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS WEB_DC, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS WEB_PAY, SUM(CASE WHEN B.ORD_CHNL_CD = 'WEB' AND B.TOT_AMT >= 1000000 THEN 1 ELSE 0 END) AS WEB_BIG_CNT, /* 앱 */ SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS APP_NET, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN 1 ELSE 0 END) AS APP_CNT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS APP_RTN, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS APP_QTY, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS APP_DC, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS APP_PAY, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' AND B.TOT_AMT >= 1000000 THEN 1 ELSE 0 END) AS APP_BIG_CNT, /* 콜센터 */ SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS CALL_NET, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN 1 ELSE 0 END) AS CALL_CNT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS CALL_RTN, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS CALL_QTY, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS CALL_DC, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS CALL_PAY, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' AND B.TOT_AMT >= 1000000 THEN 1 ELSE 0 END) AS CALL_BIG_CNT, /* 매장 */ SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS STORE_NET, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN 1 ELSE 0 END) AS STORE_CNT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS STORE_RTN, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS STORE_QTY, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS STORE_DC, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS STORE_PAY, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' AND B.TOT_AMT >= 1000000 THEN 1 ELSE 0 END) AS STORE_BIG_CNT, /* 기업 */ SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS B2B_NET, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN 1 ELSE 0 END) AS B2B_CNT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS B2B_RTN, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS B2B_QTY, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS B2B_DC, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS B2B_PAY, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' AND B.TOT_AMT >= 1000000