= 'WEB' AND B.TOT_AMT >= 1000000 THEN 1 ELSE 0 END) AS WEB_BIG_CNT, /* 앱 */ SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS APP_NET, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN 1 ELSE 0 END) AS APP_CNT, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS APP_RTN, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS APP_QTY, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS APP_DC, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS APP_PAY, SUM(CASE WHEN B.ORD_CHNL_CD = 'APP' AND B.TOT_AMT >= 1000000 THEN 1 ELSE 0 END) AS APP_BIG_CNT, /* 콜센터 */ SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS CALL_NET, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN 1 ELSE 0 END) AS CALL_CNT, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS CALL_RTN, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS CALL_QTY, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS CALL_DC, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS CALL_PAY, SUM(CASE WHEN B.ORD_CHNL_CD = 'CALL' AND B.TOT_AMT >= 1000000 THEN 1 ELSE 0 END) AS CALL_BIG_CNT, /* 매장 */ SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS STORE_NET, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN 1 ELSE 0 END) AS STORE_CNT, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS STORE_RTN, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS STORE_QTY, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS STORE_DC, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS STORE_PAY, SUM(CASE WHEN B.ORD_CHNL_CD = 'STORE' AND B.TOT_AMT >= 1000000 THEN 1 ELSE 0 END) AS STORE_BIG_CNT, /* 기업 */ SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) ELSE 0 END) AS B2B_NET, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN 1 ELSE 0 END) AS B2B_CNT, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' AND RT.RTN_CNT > 0 THEN RT.RTN_SUM ELSE 0 END) AS B2B_RTN, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN NVL(I.ITEM_QTY, 0) ELSE 0 END) AS B2B_QTY, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN NVL(CP.DC_SUM, 0) ELSE 0 END) AS B2B_DC, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' THEN NVL(PY.PAY_SUM, 0) ELSE 0 END) AS B2B_PAY, SUM(CASE WHEN B.ORD_CHNL_CD = 'B2B' AND B.TOT_AMT >= 1000000 THEN 1 ELSE 0 END) AS B2B_BIG_CNT, SUM(NVL(PY.PAY_SUM, 0)) AS PAY_TOTAL, MAX(B.ORD_DT) AS LAST_ORD_DT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN CPN_AGG CP ON CP.ORD_NO = B.ORD_NO LEFT JOIN RTN_AGG RT ON RT.ORD_NO = B.ORD_NO LEFT JOIN PAY_AGG PY ON PY.ORD_NO = B.ORD_NO WHERE B.ORD_YM = #year# || '12' GROUP BY B.CUST_NO ) SELECT B.CUST_NO AS CUST_KEY, MAX(B.CUST_NAME) AS CUST_NAME, MAX((SELECT G.CD_NM FROM TB_CMM_CD G WHERE G.GRP_CD = 'CUST_GRD' AND G.CD = B.CUST_GRD)) AS CUST_GRD_NM, MAX(ED.EMP_NM || ' (' || ED.DEPT_NM || ')') AS SALES_REP, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT, SUM(B.TOT_AMT) AS ORD_AMT, SUM(NVL(I.ITEM_AMT, 0)) AS ITEM_AMT, SUM(NVL(I.ITEM_QTY, 0)) AS ITEM_QTY, SUM(NVL(PY.PAY_SUM, 0)) AS PAY_AMT, SUM(NVL(PY.CARD_SUM, 0)) AS CARD_AMT, SUM(NVL(PY.BANK_SUM, 0)) AS BANK_AMT, SUM(NVL(PY.POINT_SUM, 0)) AS POINT_AMT, SUM(NVL(CP.DC_SUM, 0)) AS DC_AMT, SUM(NVL(RT.RTN_SUM, 0)) AS RTN_AMT, SUM(CASE WHEN DL.DLV_STAT_CD = 'DONE' THEN 1 ELSE 0 END) AS DLV_DONE_CNT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS DLV_LATE_CNT, SUM(DECODE(DL.DLV_CMP_CD, 'CJ', 1, 0)) AS DLV_CJ_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' AND B.ORD_CHNL_CD = 'WEB' THEN 1 ELSE 0 END) AS GRD_VVIP_WEB_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' AND B.ORD_CHNL_CD = 'APP' THEN 1 ELSE 0 END) AS GRD_VVIP_APP_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' AND B.ORD_CHNL_CD = 'CALL' THEN 1 ELSE 0 END) AS GRD_VVIP_CALL_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' AND B.ORD_CHNL_CD = 'STORE' THEN 1 ELSE 0 END) AS GRD_VVIP_STORE_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' AND B.ORD_CHNL_CD = 'B2B' THEN 1 ELSE 0 END) AS GRD_VVIP_B2B_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) - NVL(RT.RTN_SUM, 0) ELSE 0 END) AS GRD_VVIP_NET, SUM(CASE WHEN B.CUST_GRD = 'VIP' AND B.ORD_CHNL_CD = 'WEB' THEN 1 ELSE 0 END) AS GRD_VIP_WEB_CNT, SUM(CASE WHEN B.CUST_GRD = 'VIP' AND B.ORD_CHNL_CD = 'APP' THEN 1 ELSE 0 END) AS GRD_VIP_APP_CNT, SUM(CASE WHEN B.CUST_GRD = 'VIP' AND B.ORD_CHNL_CD = 'CALL' THEN 1 ELSE 0 END) AS GRD_VIP_CALL_CNT, SUM(CASE WHEN B.CUST_GRD = 'VIP' AND B.ORD_CHNL_CD = 'STORE' THEN 1 ELSE 0 END) AS GRD_VIP_STORE_CNT, SUM(CASE WHEN B.CUST_GRD = 'VIP' AND B.ORD_CHNL_CD = 'B2B' THEN 1 ELSE 0 END) AS GRD_VIP_B2B_CNT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) - NVL(RT.RTN_SUM, 0) ELSE 0 END) AS GRD_VIP_NET, SUM(CASE WHEN B.CUST_GRD = 'GOLD' AND B.ORD_CHNL_CD = 'WEB' THEN 1 ELSE 0 END) AS GRD_GOLD_WEB_CNT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' AND B.ORD_CHNL_CD = 'APP' THEN 1 ELSE 0 END) AS GRD_GOLD_APP_CNT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' AND B.ORD_CHNL_CD = 'CALL' THEN 1 ELSE 0 END) AS GRD_GOLD_CALL_CNT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' AND B.ORD_CHNL_CD = 'STORE' THEN 1 ELSE 0 END) AS GRD_GOLD_STORE_CNT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' AND B.ORD_CHNL_CD = 'B2B' THEN 1 ELSE 0 END) AS GRD_GOLD_B2B_CNT, SUM(CASE WHEN B.CUST_GRD = 'GOLD' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) - NVL(RT.RTN_SUM, 0) ELSE 0 END) AS GRD_GOLD_NET, SUM(CASE WHEN B.CUST_GRD = 'SILVER' AND B.ORD_CHNL_CD = 'WEB' THEN 1 ELSE 0 END) AS GRD_SILVER_WEB_CNT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' AND B.ORD_CHNL_CD = 'APP' THEN 1 ELSE 0 END) AS GRD_SILVER_APP_CNT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' AND B.ORD_CHNL_CD = 'CALL' THEN 1 ELSE 0 END) AS GRD_SILVER_CALL_CNT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' AND B.ORD_CHNL_CD = 'STORE' THEN 1 ELSE 0 END) AS GRD_SILVER_STORE_CNT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' AND B.ORD_CHNL_CD = 'B2B' THEN 1 ELSE 0 END) AS GRD_SILVER_B2B_CNT, SUM(CASE WHEN B.CUST_GRD = 'SILVER' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) - NVL(RT.RTN_SUM, 0) ELSE 0 END) AS GRD_SILVER_NET, SUM(CASE WHEN B.CUST_GRD = 'BASIC' AND B.ORD_CHNL_CD = 'WEB' THEN 1 ELSE 0 END) AS GRD_BASIC_WEB_CNT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' AND B.ORD_CHNL_CD = 'APP' THEN 1 ELSE 0 END) AS GRD_BASIC_APP_CNT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' AND B.ORD_CHNL_CD = 'CALL' THEN 1 ELSE 0 END) AS GRD_BASIC_CALL_CNT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' AND B.ORD_CHNL_CD = 'STORE' THEN 1 ELSE 0 END) AS GRD_BASIC_STORE_CNT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' AND B.ORD_CHNL_CD = 'B2B' THEN 1 ELSE 0 END) AS GRD_BASIC_B2B_CNT, SUM(CASE WHEN B.CUST_GRD = 'BASIC' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) - NVL(RT.RTN_SUM, 0) ELSE 0 END) AS GRD_BASIC_NET, SUM(NVL(M01.WEB_NET, 0)) AS M01_WEB_NET, SUM(NVL(M01.WEB_CNT, 0) - NVL(M01.WEB_RTN, 0) / 10000) AS M01_WEB_IDX, SUM(NVL(M01.WEB_PAY, 0) - NVL(M01.WEB_DC, 0)) AS M01_WEB_CASH, SUM(NVL(M01.WEB_BIG_CNT, 0)) AS M01_WEB_BIG, SUM(NVL(M01.APP_NET, 0)) AS M01_APP_NET, SUM(NVL(M01.APP_CNT, 0) - NVL(M01.APP_RTN, 0) / 10000) AS M01_APP_IDX, SUM(NVL(M01.APP_PAY, 0) - NVL(M01.APP_DC, 0)) AS M01_APP_CASH, SUM(NVL(M01.APP_BIG_CNT, 0)) AS M01_APP_BIG, SUM(NVL(M01.CALL_NET, 0)) AS M01_CALL_NET, SUM(NVL(M01.CALL_CNT, 0) - NVL(M01.CALL_RTN, 0) / 10000) AS M01_CALL_IDX, SUM(NVL(M01.CALL_PAY, 0) - NVL(M01.CALL_DC, 0)) AS M01_CALL_CASH, SUM(NVL(M01.CALL_BIG_CNT, 0)) AS M01_CALL_BIG, SUM(NVL(M01.STORE_NET, 0)) AS M01_STORE_NET, SUM(NVL(M01.STORE_CNT, 0) - NVL(M01.STORE_RTN, 0) / 10000) AS M01_STORE_IDX, SUM(NVL(M01.STORE_PAY, 0) - NVL(M01.STORE_DC, 0)) AS M01_STORE_CASH, SUM(NVL(M01.STORE_BIG_CNT, 0)) AS M01_STORE_BIG, SUM(NVL(M01.B2B_NET, 0)) AS M01_B2B_NET, SUM(NVL(M01.B2B_CNT, 0) - NVL(M01.B2B_RTN, 0) / 10000) AS M01_B2B_IDX, SUM(NVL(M01.B2B_PAY, 0) - NVL(M01.B2B_DC, 0)) AS M01_B2B_CASH, SUM(NVL(M01.B2B_BIG_CNT,