B.CUST_NO IN (SELECT S.CUST_NO FROM ORD_BASE S GROUP BY S.CUST_NO HAVING COUNT(*) >= #minOrdCnt#)
GROUP BY B.CUST_NO UNION ALL SELECT 'TOTAL' AS CUST_KEY, '합계' AS CUST_NAME, NULL AS CUST_GRD_NM, NULL AS SALES_REP, COUNT(DISTINCT B.ORD_NO) AS ORD_CNT, SUM(B.TOT_AMT) AS ORD_AMT, SUM(NVL(I.ITEM_AMT, 0)) AS ITEM_AMT, SUM(NVL(I.ITEM_QTY, 0)) AS ITEM_QTY, SUM(NVL(PY.PAY_SUM, 0)) AS PAY_AMT, SUM(NVL(PY.CARD_SUM, 0)) AS CARD_AMT, SUM(NVL(PY.BANK_SUM, 0)) AS BANK_AMT, SUM(NVL(PY.POINT_SUM, 0)) AS POINT_AMT, SUM(NVL(CP.DC_SUM, 0)) AS DC_AMT, SUM(NVL(RT.RTN_SUM, 0)) AS RTN_AMT, SUM(CASE WHEN DL.DLV_STAT_CD = 'DONE' THEN 1 ELSE 0 END) AS DLV_DONE_CNT, SUM(CASE WHEN DL.DLV_DT > DL.DLV_REQ_DT THEN 1 ELSE 0 END) AS DLV_LATE_CNT, SUM(DECODE(DL.DLV_CMP_CD, 'CJ', 1, 0)) AS DLV_CJ_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' AND B.ORD_CHNL_CD = 'WEB' THEN 1 ELSE 0 END) AS GRD_VVIP_WEB_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' AND B.ORD_CHNL_CD = 'APP' THEN 1 ELSE 0 END) AS GRD_VVIP_APP_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' AND B.ORD_CHNL_CD = 'CALL' THEN 1 ELSE 0 END) AS GRD_VVIP_CALL_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' AND B.ORD_CHNL_CD = 'STORE' THEN 1 ELSE 0 END) AS GRD_VVIP_STORE_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' AND B.ORD_CHNL_CD = 'B2B' THEN 1 ELSE 0 END) AS GRD_VVIP_B2B_CNT, SUM(CASE WHEN B.CUST_GRD = 'VVIP' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) - NVL(RT.RTN_SUM, 0) ELSE 0 END) AS GRD_VVIP_NET, SUM(CASE WHEN B.CUST_GRD = 'VIP' AND B.ORD_CHNL_CD = 'WEB' THEN 1 ELSE 0 END) AS GRD_VIP_WEB_CNT, SUM(CASE WHEN B.CUST_GRD = 'VIP' AND B.ORD_CHNL_CD = 'APP' THEN 1 ELSE 0 END) AS GRD_VIP_APP_CNT, SUM(CASE WHEN B.CUST_GRD = 'VIP' AND B.ORD_CHNL_CD = 'CALL' THEN 1 ELSE 0 END) AS GRD_VIP_CALL_CNT, SUM(CASE WHEN B.CUST_GRD = 'VIP' AND B.ORD_CHNL_CD = 'STORE' THEN 1 ELSE 0 END) AS GRD_VIP_STORE_CNT, SUM(CASE WHEN B.CUST_GRD = 'VIP' AND B.ORD_CHNL_CD = 'B2B' THEN 1 ELSE 0 END) AS GRD_VIP_B2B_CNT, SUM(CASE WHEN B.CUST_GRD = 'VIP' THEN NVL(I.ITEM_AMT, 0) - NVL(CP.DC_SUM, 0) - NVL(RT.RTN_SUM, 0) ELSE 0 END) AS GRD_VIP_NET, SUM(CASE WHEN B.CUST_GRD = 'GOLD' AND B.ORD_CHNL_CD = 'WEB' THEN