.VVIP_AMT, 0) + NVL(R_SEJONG.VIP_AMT, 0)) AS R_SEJONG_TOP_AMT, SUM(NVL(R_GYEONGGI.VVIP_AMT, 0) + NVL(R_GYEONGGI.VIP_AMT, 0)) AS R_GYEONGGI_TOP_AMT, SUM(NVL(R_GANGWON.VVIP_AMT, 0) + NVL(R_GANGWON.VIP_AMT, 0)) AS R_GANGWON_TOP_AMT, SUM(NVL(R_CHUNGBUK.VVIP_AMT, 0) + NVL(R_CHUNGBUK.VIP_AMT, 0)) AS R_CHUNGBUK_TOP_AMT, SUM(NVL(R_CHUNGNAM.VVIP_AMT, 0) + NVL(R_CHUNGNAM.VIP_AMT, 0)) AS R_CHUNGNAM_TOP_AMT, SUM(NVL(R_JEONBUK.VVIP_AMT, 0) + NVL(R_JEONBUK.VIP_AMT, 0)) AS R_JEONBUK_TOP_AMT, SUM(NVL(R_JEONNAM.VVIP_AMT, 0) + NVL(R_JEONNAM.VIP_AMT, 0)) AS R_JEONNAM_TOP_AMT, SUM(NVL(R_GYEONGBUK.VVIP_AMT, 0) + NVL(R_GYEONGBUK.VIP_AMT, 0)) AS R_GYEONGBUK_TOP_AMT, SUM(NVL(R_GYEONGNAM.VVIP_AMT, 0) + NVL(R_GYEONGNAM.VIP_AMT, 0)) AS R_GYEONGNAM_TOP_AMT, SUM(NVL(R_JEJU.VVIP_AMT, 0) + NVL(R_JEJU.VIP_AMT, 0)) AS R_JEJU_TOP_AMT, SUM(NVL(R_SEOUL.LATE_CNT, 0)) AS R_SEOUL_LATE, SUM(NVL(R_BUSAN.LATE_CNT, 0)) AS R_BUSAN_LATE, SUM(NVL(R_DAEGU.LATE_CNT, 0)) AS R_DAEGU_LATE, SUM(NVL(R_INCHEON.LATE_CNT, 0)) AS R_INCHEON_LATE, SUM(NVL(R_GWANGJU.LATE_CNT, 0)) AS R_GWANGJU_LATE, SUM(NVL(R_DAEJEON.LATE_CNT, 0)) AS R_DAEJEON_LATE, SUM(NVL(R_ULSAN.LATE_CNT, 0)) AS R_ULSAN_LATE, SUM(NVL(R_SEJONG.LATE_CNT, 0)) AS R_SEJONG_LATE, SUM(NVL(R_GYEONGGI.LATE_CNT, 0)) AS R_GYEONGGI_LATE, SUM(NVL(R_GANGWON.LATE_CNT, 0)) AS R_GANGWON_LATE, SUM(NVL(R_CHUNGBUK.LATE_CNT, 0)) AS R_CHUNGBUK_LATE, SUM(NVL(R_CHUNGNAM.LATE_CNT, 0)) AS R_CHUNGNAM_LATE, SUM(NVL(R_JEONBUK.LATE_CNT, 0)) AS R_JEONBUK_LATE, SUM(NVL(R_JEONNAM.LATE_CNT, 0)) AS R_JEONNAM_LATE, SUM(NVL(R_GYEONGBUK.LATE_CNT, 0)) AS R_GYEONGBUK_LATE, SUM(NVL(R_GYEONGNAM.LATE_CNT, 0)) AS R_GYEONGNAM_LATE, SUM(NVL(R_JEJU.LATE_CNT, 0)) AS R_JEJU_LATE, SUM(NVL(CS.CTG_AMT, 0)) AS CTG_AMT, MAX(CS.TOP_CTG_NM) AS TOP_CTG_NM, MAX(B.ORD_DT) AS LAST_ORD_DT FROM ORD_BASE B LEFT JOIN ITEM_AGG I ON I.ORD_NO = B.ORD_NO LEFT JOIN PAY_AGG PY ON PY.ORD_NO = B.ORD_NO LEFT JOIN CPN_AGG CP ON CP.ORD_NO = B.ORD_NO LEFT JOIN RTN_AGG RT ON RT.ORD_NO = B.ORD_NO LEFT JOIN DLV_LAST DL ON DL.ORD_NO = B.ORD_NO LEFT JOIN EMP_DEPT ED ON ED.EMP_NO = B.SALE_EMP_NO LEFT JOIN CTG_SALES CS ON CS.ORD_NO = B.ORD_NO LEFT JOIN R_SEOUL ON R_SEOUL.CUST_NO = B.CUST_NO LEFT JOIN R_BUSAN ON R_BUSAN.CUST_NO = B.CUST_NO LEFT JOIN R_DAEGU ON R_DAEGU.CUST_NO = B.CUST_NO LEFT JOIN R_INCHEON ON R_INCHEON.CUST_NO = B.CUST_NO LEFT JOIN R_GWANGJU ON R_GWANGJU.CUST_NO = B.CUST_NO LEFT JOIN R_DAEJEON ON R_DAEJEON.CUST_NO = B.CUST_NO LEFT JOIN R_ULSAN ON R_ULSAN.CUST_NO = B.CUST_NO LEFT JOIN R_SEJONG ON R_SEJONG.CUST_NO = B.CUST_NO LEFT JOIN R_GYEONGGI ON R_GYEONGGI.CUST_NO = B.CUST_NO LEFT JOIN R_GANGWON ON R_GANGWON.CUST_NO = B.CUST_NO LEFT JOIN R_CHUNGBUK ON R_CHUNGBUK.CUST_NO = B.CUST_NO LEFT JOIN R_CHUNGNAM ON R_CHUNGNAM.CUST_NO = B.CUST_NO LEFT JOIN R_JEONBUK ON R_JEONBUK.CUST_NO = B.CUST_NO LEFT JOIN R_JEONNAM ON R_JEONNAM.CUST_NO = B.CUST_NO LEFT JOIN R_GYEONGBUK ON R_GYEONGBUK.CUST_NO = B.CUST_NO LEFT JOIN R_GYEONGNAM ON R_GYEONGNAM.CUST_NO = B.CUST_NO LEFT JOIN R_JEJU ON R_JEJU.CUST_NO = B.CUST_NO LEFT JOIN M01 ON M01.CUST_NO = B.CUST_NO LEFT JOIN M02 ON M02.CUST_NO = B.CUST_NO LEFT JOIN M03 ON M03.CUST_NO = B.CUST_NO LEFT JOIN M04 ON M04.CUST_NO = B.CUST_NO LEFT JOIN M05 ON M05.CUST_NO = B.CUST_NO LEFT JOIN M06 ON M06.CUST_NO = B.CUST_NO LEFT JOIN M07 ON M07.CUST_NO = B.CUST_NO LEFT JOIN M08 ON M08.CUST_NO = B.CUST_NO LEFT JOIN M09 ON M09.CUST_NO = B.CUST_NO LEFT JOIN M10 ON M10.CUST_NO = B.CUST_NO LEFT JOIN M11 ON M11.CUST_NO = B.CUST_NO LEFT JOIN M12 ON M12.CUST_NO = B.CUST_NO WHERE 1 = 1
